export function parseAmount(raw){if(raw===null||raw===undefined||String(raw).trim()==='')return null;if(typeof raw==='number')return Number.isFinite(raw)?raw:NaN;let text=String(raw).trim().replace(/\s/g,'');if(!/^[\d.,]+$/.test(text))return NaN;const comma=text.lastIndexOf(','),dot=text.lastIndexOf('.');if(comma>=0&&dot>=0){const decimal=comma>dot?',':'.',group=decimal===','?'.':',';text=text.replaceAll(group,'').replace(decimal,'.');}else if(comma>=0){text=/^\d{1,3}(,\d{3})+$/.test(text)?text.replaceAll(',',''):text.replace(',','.');}else if(dot>=0&&/^\d{1,3}(\.\d{3})+$/.test(text))text=text.replaceAll('.','');const number=Number(text);return Number.isFinite(number)?number:NaN;}
export function formatAmount(raw){const number=parseAmount(raw);return number===null?'':Number.isFinite(number)?number.toLocaleString('en-US',{maximumFractionDigits:2}):'';}
export function bindAmountInput(input,onChange=()=>{}){input.type='text';input.inputMode='decimal';input.removeAttribute('min');input.removeAttribute('step');input.autocomplete='off';const format=()=>{const original=input.value,caret=input.selectionStart??original.length,rightDigits=(original.slice(caret).match(/\d/g)||[]).length;let raw=original.replace(/[^\d.,]/g,'');if(raw.includes(',')&&/^\d{1,3}(,\d{3})*(\.\d{0,2})?$/.test(raw))raw=raw.replaceAll(',','');else if(!raw.includes('.'))raw=raw.replaceAll(',','');else if(/^\d{1,3}(\.\d{3})+$/.test(raw))raw=raw.replaceAll('.','');else raw=raw.replaceAll(',','');const [integer,...fraction]=raw.split('.'),dec=fraction.length?fraction.join('').slice(0,2):null;input.value=integer?Number(integer).toLocaleString('en-US')+(dec!==null?'.'+dec:''):raw==='.'?'0.':'';let next=input.value.length,count=0;while(next>0&&count<rightDigits){next--;if(/\d/.test(input.value[next]))count++;}try{input.setSelectionRange(next,next);}catch{}onChange();};input.addEventListener('input',format);input.addEventListener('blur',()=>{input.value=formatAmount(input.value);onChange();});return{set(value){input.value=formatAmount(value);},value(){return parseAmount(input.value);}};}
